import{_ as t,H as i,f as l,i as a}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"56 | RESTfulWebServices（20）：为什么要通过测试的方法来驱动出代码结构？","description":"","frontmatter":{},"headers":[{"level":2,"title":"回顾架构愿景与任务列表","slug":"回顾架构愿景与任务列表","link":"#回顾架构愿景与任务列表","children":[]},{"level":2,"title":"视频演示","slug":"视频演示","link":"#视频演示","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"徐昊·TDD项目实战70讲/56｜RESTfulWebServices（20）：为什么要通过测试的方法来驱动出代码结构？.md","filePath":"徐昊·TDD项目实战70讲/56｜RESTfulWebServices（20）：为什么要通过测试的方法来驱动出代码结构？.md","lastUpdated":1795563222000}'),s={name:"徐昊·TDD项目实战70讲/56｜RESTfulWebServices（20）：为什么要通过测试的方法来驱动出代码结构？.md"};function r(o,e,p,n,E,u){return i(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="_56-restfulwebservices-20-为什么要通过测试的方法来驱动出代码结构" tabindex="-1">56 | RESTfulWebServices（20）：为什么要通过测试的方法来驱动出代码结构？ <a class="header-anchor" href="#_56-restfulwebservices-20-为什么要通过测试的方法来驱动出代码结构" aria-label="Permalink to &quot;56 | RESTfulWebServices（20）：为什么要通过测试的方法来驱动出代码结构？&quot;">​</a></h1><p>你好，我是徐昊。今天我们继续使用 TDD 的方式实现 RESTful Web Services。</p><h2 id="回顾架构愿景与任务列表" tabindex="-1">回顾架构愿景与任务列表 <a class="header-anchor" href="#回顾架构愿景与任务列表" aria-label="Permalink to &quot;回顾架构愿景与任务列表&quot;">​</a></h2><p>目前我们已经实现了 ResourceRouter，和 UriTemplate 整体的架构愿景如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/56/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/56/1.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/56/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/56/2.png" alt=""></a></p><p>接下来要进入 RootResource/Resource 和 ResourceMethod 的开发。目前未经细化的任务列表如下：</p><ul><li><p>Resource/RootResource/ResourceMethod</p></li><li><p>在处理请求派分时，可以支持多级子资源（Sub-Resource）</p></li><li><p>在处理请求派分时，可以根据客户端提供的超媒体类型，选择对应的资源方法（Resource Method）</p></li><li><p>在处理请求派分时，可以根据客户端提供的 Http 方法，选择对应的资源方法</p></li><li><p>资源方法可以返回 Java 对象，由 Runtime 自行推断正确的返回状态</p></li><li><p>资源方法可以不明确指定返回的超媒体类型，由 Runtime 自行推断，比如，资源方法标注了 Produces 标注，那么就使用标注提供的超媒体类型等</p></li><li><p>资源方法可按找期望的类型，访问 Http 请求的内容</p></li><li><p>资源对象和资源方法可接受环境组件的注入</p></li></ul><p>让我们细化一下任务列表。首先关注在请求派分的 Uri 匹配部分，暂时忽略其他部分：</p><ul><li><p>Resource/RootResource/ResourceMethod</p></li><li><p>从 Path 标注中获取 UriTemplate</p></li><li><p>如不存在 Path 标注，则抛出异常</p></li><li><p>在处理请求派分时，可以根据客户端提供的 Http 方法，选择对应的资源方法</p></li><li><p>当请求与资源方法的 Uri 模版一致，且 Http 方法一致时，派分到该方法</p></li><li><p>没有资源方法于请求的 Uri 和 Http 方法一致时，返回 404</p></li><li><p>在处理请求派分时，可以支持多级子资源</p></li><li><p>当没有资源方法可以匹配请求时，选择最优匹配 SubResourceLocater，通过它继续进行派分</p></li><li><p>如果 SubResourceLocator 也无法找到满足的请求时，返回 404</p></li></ul><h2 id="视频演示" tabindex="-1">视频演示 <a class="header-anchor" href="#视频演示" aria-label="Permalink to &quot;视频演示&quot;">​</a></h2><p>进入今天的环节：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/56/3.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/56/3.jpeg" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>按照三角法，接下来要如何增加新的测试案例？</p>',15)])])}const _=t(s,[["render",r]]);export{h as __pageData,_ as default};
